package kr.ivlis.ivlyricsandroid;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * The Pronunciation Lab page's contract without a WebView: the scripts the app evaluates in the page
 * and the messages the page posts back. The page (assets/pronunciation-lab/PronunciationLabPage.html)
 * is generated by the desktop ivLyrics repository from src/providers/ai/pronunciationLabMobileBridge.mjs
 * (.github/scripts/build_pronunciation_lab_mobile.mjs) and is never edited here.
 *
 * <p>App to page: {@code ivLyricsPronunciationLab.convert(id, request)} and {@code .cancel(id)}.
 * Page to app, as JSON strings through {@code ivLyricsPronunciationLabNative.postMessage}:
 * {@code {type:"ready"}} once, {@code {type:"result", id, lines, version}} with exactly one line per
 * requested line, and {@code {type:"error", id, code, message}} with a {@code PRONUNCIATION_LAB_*} code.
 * Streaming ({@code type:"line"}) is never requested.
 *
 * <p>Plain Java without Android or org.json types, so JVM unit tests cover it.
 */
final class PronunciationLabProtocol {
    static final String LABEL = "Pronunciation Lab";

    // Codes the page sends.
    static final String UNSUPPORTED_SOURCE = "PRONUNCIATION_LAB_UNSUPPORTED_SOURCE";
    static final String UNSUPPORTED_TARGET = "PRONUNCIATION_LAB_UNSUPPORTED_TARGET";
    static final String LOAD_FAILED = "PRONUNCIATION_LAB_LOAD_FAILED";
    static final String ABORTED = "PRONUNCIATION_LAB_ABORTED";
    static final String BAD_REQUEST = "PRONUNCIATION_LAB_BAD_REQUEST";
    static final String FAILED = "PRONUNCIATION_LAB_FAILED";
    // App-side codes; the page never sends these.
    /** The page did not answer within {@link PronunciationLabRepository#REQUEST_TIMEOUT_MS}. */
    static final String TIMEOUT = "PRONUNCIATION_LAB_TIMEOUT";
    /** There is no page: no WebView or page asset, a failed load, or a renderer that died. */
    static final String UNAVAILABLE = "PRONUNCIATION_LAB_UNAVAILABLE";

    private static final String CODE_PREFIX = "PRONUNCIATION_LAB_";
    private static final String BRIDGE = "window.ivLyricsPronunciationLab";
    private static final int MAX_JSON_DEPTH = 32;

    private PronunciationLabProtocol() {
    }

    /** Line pronunciation of the given lines, in order; blocks until the page answers. */
    interface Converter {
        List<String> convert(Request request) throws Exception;
    }

    /** One convert call: the lyric rows the AI providers would get, and how to write them. */
    static final class Request {
        final List<String> lines;
        /** The song's language code as the AI pronunciation prompt names it ("ja", "zh-TW", "auto"...). */
        final String sourceLang;
        /** The pronunciation language code ("ko", "en", "ja"...). */
        final String lang;
        /** "translation" (the target language's own script), "latin" or "ipa". */
        final String notation;

        Request(List<String> lines, String sourceLang, String lang, String notation) {
            List<String> copy = new ArrayList<>();
            if (lines != null) {
                for (String line : lines) {
                    copy.add(line == null ? "" : line);
                }
            }
            this.lines = Collections.unmodifiableList(copy);
            String source = sourceLang == null ? "" : sourceLang.trim();
            this.sourceLang = source.isEmpty() ? "auto" : source;
            this.lang = lang == null ? "" : lang.trim();
            this.notation = notation(notation);
        }
    }

    enum Kind { READY, RESULT, ERROR, LINE, UNKNOWN, MALFORMED }

    /** A message from the page. Fields that do not belong to the kind are empty. */
    static final class Message {
        final Kind kind;
        final String id;
        final List<String> lines;
        final String version;
        final String code;
        final String text;

        private Message(Kind kind, String id, List<String> lines, String version, String code, String text) {
            this.kind = kind;
            this.id = id;
            this.lines = lines;
            this.version = version;
            this.code = code;
            this.text = text;
        }

        private static Message of(Kind kind, String id) {
            return new Message(kind, id, Collections.emptyList(), "", "", "");
        }
    }

    /**
     * A failed request. The page's codes that tell the user something (the song's language, the
     * pronunciation language, a failed download) have their own message; anything else reads as the
     * provider being unavailable, the message the keyless translators use. The detail stays in the log.
     */
    static final class Failure extends KeylessTranslationProviders.ProviderException {
        final String code;

        Failure(String code, String detail) {
            super(messageKey(codeOf(code)), codeOf(code) + ": " + (detail == null ? "" : detail.trim()), LABEL);
            this.code = codeOf(code);
        }

        private static String codeOf(String code) {
            return code == null || code.trim().isEmpty() ? FAILED : code.trim();
        }
    }

    /** The AppI18n key of a failure code's user message; formatted with {@link #LABEL}. */
    static String messageKey(String code) {
        if (UNSUPPORTED_SOURCE.equals(code)) return "error.pronunciation_lab_unsupported_source";
        if (UNSUPPORTED_TARGET.equals(code)) return "error.pronunciation_lab_unsupported_target";
        if (LOAD_FAILED.equals(code)) return "error.pronunciation_lab_load_failed";
        return "error.provider_unavailable_format";
    }

    /** The app's pronunciation notation as the page names it: "latin", "ipa", or "translation" (the default). */
    static String notation(String value) {
        String normalized = value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
        return "latin".equals(normalized) || "ipa".equals(normalized) ? normalized : "translation";
    }

    /** Starts a request; a running request with the same id is replaced by the page. */
    static String convertScript(String id, Request request) {
        // The request goes as a JSON string, which the page parses; its returned Promise is not needed.
        return BRIDGE + ".convert(" + quote(id) + "," + quote(requestJson(request)) + ");void 0;";
    }

    static String cancelScript(String id) {
        return BRIDGE + "&&" + BRIDGE + ".cancel(" + quote(id) + ");void 0;";
    }

    static String requestJson(Request request) {
        StringBuilder json = new StringBuilder(64 + request.lines.size() * 24).append("{\"lines\":[");
        for (int index = 0; index < request.lines.size(); index++) {
            if (index > 0) json.append(',');
            json.append(quote(request.lines.get(index)));
        }
        return json.append("],\"sourceLang\":").append(quote(request.sourceLang))
                .append(",\"lang\":").append(quote(request.lang))
                .append(",\"notation\":").append(quote(request.notation))
                .append('}')
                .toString();
    }

    /**
     * A JSON string literal that is also a valid JavaScript string literal: U+2028/U+2029, control
     * characters and unpaired surrogates are escaped, so any lyric survives evaluateJavascript intact.
     */
    static String quote(String value) {
        String text = value == null ? "" : value;
        StringBuilder quoted = new StringBuilder(text.length() + 2).append('"');
        for (int index = 0; index < text.length(); index++) {
            char character = text.charAt(index);
            switch (character) {
                case '"': quoted.append("\\\""); break;
                case '\\': quoted.append("\\\\"); break;
                case '\n': quoted.append("\\n"); break;
                case '\r': quoted.append("\\r"); break;
                case '\t': quoted.append("\\t"); break;
                case '\b': quoted.append("\\b"); break;
                case '\f': quoted.append("\\f"); break;
                default:
                    boolean paired = Character.isHighSurrogate(character)
                            ? index + 1 < text.length() && Character.isLowSurrogate(text.charAt(index + 1))
                            : Character.isLowSurrogate(character)
                            && index > 0 && Character.isHighSurrogate(text.charAt(index - 1));
                    if (character < 0x20 || character == '\u2028' || character == '\u2029'
                            || (Character.isSurrogate(character) && !paired)) {
                        quoted.append(String.format(Locale.ROOT, "\\u%04x", (int) character));
                    } else {
                        quoted.append(character);
                    }
            }
        }
        return quoted.append('"').toString();
    }

    /** Reads one message; anything that is not a JSON object of the contract's shape is MALFORMED. */
    static Message parse(String json) {
        Object value;
        try {
            value = new JsonReader(json == null ? "" : json).document();
        } catch (IllegalArgumentException malformed) {
            return Message.of(Kind.MALFORMED, "");
        }
        if (!(value instanceof Map)) {
            return Message.of(Kind.MALFORMED, "");
        }
        Map<?, ?> object = (Map<?, ?>) value;
        Object type = object.get("type");
        String id = object.get("id") instanceof String ? (String) object.get("id") : "";
        if ("ready".equals(type)) {
            return Message.of(Kind.READY, "");
        }
        if ("result".equals(type)) {
            Object rawLines = object.get("lines");
            if (id.isEmpty() || !(rawLines instanceof List)) {
                return Message.of(Kind.MALFORMED, id);
            }
            List<String> lines = new ArrayList<>();
            for (Object line : (List<?>) rawLines) {
                lines.add(line == null ? "" : line instanceof String ? (String) line : String.valueOf(line));
            }
            return new Message(Kind.RESULT, id, Collections.unmodifiableList(lines), text(object.get("version")), "", "");
        }
        if ("error".equals(type)) {
            if (id.isEmpty()) {
                return Message.of(Kind.MALFORMED, id);
            }
            String code = text(object.get("code"));
            return new Message(Kind.ERROR, id, Collections.emptyList(), "",
                    code.startsWith(CODE_PREFIX) ? code : FAILED, text(object.get("message")));
        }
        return Message.of("line".equals(type) ? Kind.LINE : Kind.UNKNOWN, id);
    }

    private static String text(Object value) {
        return value instanceof String ? (String) value : "";
    }

    /** A strict reader for the JSON the page's JSON.stringify writes. Throws IllegalArgumentException. */
    private static final class JsonReader {
        private final String text;
        private int index;
        private int depth;

        JsonReader(String text) {
            this.text = text;
        }

        Object document() {
            Object value = value();
            whitespace();
            if (index != text.length()) throw malformed();
            return value;
        }

        private Object value() {
            whitespace();
            if (index >= text.length()) throw malformed();
            char character = text.charAt(index);
            switch (character) {
                case '{': return object();
                case '[': return array();
                case '"': return string();
                case 't': return literal("true", Boolean.TRUE);
                case 'f': return literal("false", Boolean.FALSE);
                case 'n': return literal("null", null);
                default:
                    if (character == '-' || (character >= '0' && character <= '9')) return number();
                    throw malformed();
            }
        }

        private Map<String, Object> object() {
            enter();
            index++;
            Map<String, Object> object = new LinkedHashMap<>();
            whitespace();
            if (consume('}')) {
                depth--;
                return object;
            }
            while (true) {
                whitespace();
                if (index >= text.length() || text.charAt(index) != '"') throw malformed();
                String key = string();
                whitespace();
                if (!consume(':')) throw malformed();
                object.put(key, value());
                whitespace();
                if (consume(',')) continue;
                if (consume('}')) {
                    depth--;
                    return object;
                }
                throw malformed();
            }
        }

        private List<Object> array() {
            enter();
            index++;
            List<Object> array = new ArrayList<>();
            whitespace();
            if (consume(']')) {
                depth--;
                return array;
            }
            while (true) {
                array.add(value());
                whitespace();
                if (consume(',')) continue;
                if (consume(']')) {
                    depth--;
                    return array;
                }
                throw malformed();
            }
        }

        private String string() {
            index++;
            StringBuilder value = new StringBuilder();
            while (true) {
                if (index >= text.length()) throw malformed();
                char character = text.charAt(index++);
                if (character == '"') return value.toString();
                if (character < 0x20) throw malformed();
                if (character != '\\') {
                    value.append(character);
                    continue;
                }
                if (index >= text.length()) throw malformed();
                char escape = text.charAt(index++);
                switch (escape) {
                    case '"': value.append('"'); break;
                    case '\\': value.append('\\'); break;
                    case '/': value.append('/'); break;
                    case 'b': value.append('\b'); break;
                    case 'f': value.append('\f'); break;
                    case 'n': value.append('\n'); break;
                    case 'r': value.append('\r'); break;
                    case 't': value.append('\t'); break;
                    case 'u': value.append(unicodeEscape()); break;
                    default: throw malformed();
                }
            }
        }

        private char unicodeEscape() {
            if (index + 4 > text.length()) throw malformed();
            int code = 0;
            for (int end = index + 4; index < end; index++) {
                int digit = Character.digit(text.charAt(index), 16);
                if (digit < 0) throw malformed();
                code = code * 16 + digit;
            }
            // Surrogate pairs arrive as two escapes and join again in the UTF-16 string.
            return (char) code;
        }

        private Object number() {
            int start = index;
            consume('-');
            if (!digits()) throw malformed();
            if (consume('.') && !digits()) throw malformed();
            if (index < text.length() && (text.charAt(index) == 'e' || text.charAt(index) == 'E')) {
                index++;
                if (!consume('+')) consume('-');
                if (!digits()) throw malformed();
            }
            try {
                return Double.valueOf(text.substring(start, index));
            } catch (NumberFormatException error) {
                throw malformed();
            }
        }

        private boolean digits() {
            int start = index;
            while (index < text.length() && text.charAt(index) >= '0' && text.charAt(index) <= '9') index++;
            return index > start;
        }

        private Object literal(String word, Object value) {
            if (!text.startsWith(word, index)) throw malformed();
            index += word.length();
            return value;
        }

        private void enter() {
            if (++depth > MAX_JSON_DEPTH) throw malformed();
        }

        private boolean consume(char expected) {
            if (index < text.length() && text.charAt(index) == expected) {
                index++;
                return true;
            }
            return false;
        }

        private void whitespace() {
            while (index < text.length()) {
                char character = text.charAt(index);
                if (character != ' ' && character != '\t' && character != '\n' && character != '\r') return;
                index++;
            }
        }

        private IllegalArgumentException malformed() {
            return new IllegalArgumentException("Malformed JSON at " + index);
        }
    }
}
